from typing import List

def kthCharacter(k: int, operations: List[int]) -> str:
    count = 0
    i = int((k).bit_length() - 1)

    if k <= 1:
        return chr(97 + (count % 26))

    while True:
        if k > (1 << i):
            if operations[i] == 1:
                count += 1
                k -= (1 << i)
        else:
            return chr(97 + (count % 26))

        i -= 1
